<?php
// Formulario de encuesta: usa el diseño celeste original y genera los campos desde MariaDB.
require __DIR__.'/common.php';
$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT e.*,GROUP_CONCAT(DISTINCT c.nombre SEPARATOR ', ') categorias FROM encuestas e LEFT JOIN encuesta_categoria ec ON ec.encuesta_id=e.id LEFT JOIN categorias c ON c.id=ec.categoria_id WHERE e.id=? AND e.estado='publicada' GROUP BY e.id");$st->execute([$id]);$survey=$st->fetch();
$questions=[];if($survey && ($survey['publico']==='publico'||logged_in())){$st=$pdo->prepare('SELECT * FROM preguntas WHERE encuesta_id=? ORDER BY orden');$st->execute([$id]);$questions=$st->fetchAll();$_SESSION['survey_tokens'][$id]=bin2hex(random_bytes(32));$token=$_SESSION['survey_tokens'][$id];}
site_start('Hospital de Clínicas | Encuesta','info','Encuesta Institucional','Su participación contribuye a mejorar la calidad de los servicios del Hospital de Clínicas.',['encuestas_buscar.html'=>'Volver a encuestas','index.html'=>'Inicio']);
?>
<?php if(!$survey || ($survey['publico']==='personal'&&!logged_in())): ?><div class="alert alert-warning text-center">La encuesta no está disponible o requiere iniciar sesión.</div><div class="text-center"><a href="encuestas_buscar.html" class="btn btn-info text-white">Volver</a></div><?php else: ?>
<section class="container py-3"><div class="col-lg-8 mx-auto"><div class="card shadow mb-4"><div class="card-header bg-info text-white"><h3 class="mb-0">Información de la encuesta</h3></div><div class="card-body"><h4><?=h($survey['titulo'])?></h4><p><?=h($survey['descripcion'])?></p><p class="mb-0"><strong>Servicio:</strong> <?=h($survey['categorias']?:'General')?></p></div></div></div>
<div class="col-lg-8 mx-auto"><div class="card shadow"><div class="card-header bg-info text-white"><h3 class="mb-0">Formulario</h3></div><div class="card-body"><div class="px-lg-4"><form method="post" action="index.php?p=responder&id=<?=$id?>"><?=csrf_field()?><input type="hidden" name="action" value="answer_survey"><input type="hidden" name="encuesta_id" value="<?=$id?>"><input type="hidden" name="token_envio" value="<?=h($token)?>">
<?php foreach($questions as $i=>$question): $op=$pdo->prepare('SELECT texto FROM opciones_pregunta WHERE pregunta_id=? ORDER BY orden');$op->execute([$question['id']]);$options=$op->fetchAll(); ?><div class="mb-5"><label class="form-label fw-bold"><?=($i+1)?>. <?=h($question['enunciado'])?> <?=$question['obligatoria']?'<span class="text-danger">*</span>':''?></label>
<?php if($question['tipo']==='valoracion'): ?><div class="d-flex flex-wrap gap-3"><?php for($n=1;$n<=5;$n++): ?><label class="form-check"><input class="form-check-input" type="radio" name="q[<?=$question['id']?>]" value="<?=$n?>" <?=$question['obligatoria']?'required':''?>><span class="form-check-label"><?=$n?></span></label><?php endfor; ?></div>
<?php elseif($question['tipo']==='select'): ?><select class="form-select" name="q[<?=$question['id']?>]" <?=$question['obligatoria']?'required':''?>><option value="">Seleccione una opción</option><?php foreach($options as $o): ?><option value="<?=h($o['texto'])?>"><?=h($o['texto'])?></option><?php endforeach; ?></select>
<?php elseif(in_array($question['tipo'],['unica','multiple'],true)): ?><?php foreach($options as $o): ?><div class="form-check"><input class="form-check-input" type="<?=$question['tipo']==='multiple'?'checkbox':'radio'?>" name="q[<?=$question['id']?>]<?=$question['tipo']==='multiple'?'[]':''?>" value="<?=h($o['texto'])?>" <?=$question['tipo']==='unica'&&$question['obligatoria']?'required':''?>><label class="form-check-label"><?=h($o['texto'])?></label></div><?php endforeach; ?>
<?php else: ?><textarea class="form-control" name="q[<?=$question['id']?>]" rows="5" placeholder="Escriba aquí su respuesta..." <?=$question['obligatoria']?'required':''?>></textarea><?php endif; ?></div><?php endforeach; ?>
<div class="alert alert-info"><strong>Importante:</strong> Las respuestas se procesan de forma anónima. No se solicita nombre ni cédula.</div><div class="d-grid gap-2"><button class="btn btn-info btn-lg text-white">Enviar respuestas</button><a href="encuestas_buscar.html" class="btn btn-outline-secondary">Cancelar</a></div></form></div></div></div></div></section>
<?php endif; ?><section class="container pb-5"><div class="col-lg-8 mx-auto"><div class="card shadow"><div class="card-body text-center"><h4>Gracias por su participación</h4><p class="mb-0">Su opinión contribuye a mejorar la calidad de los servicios brindados por el Hospital de Clínicas.</p></div></div></div></section>
<?php site_end(); ?>
